"""
NGAP Protocol Messages Definition Module for PCAP Analysis.
This module provides predefined NGAP (NG Application Protocol) message definitions and factory functions
for creating awaited messages used in PCAP file analysis.
The module defines AwaitedMessage objects that can be used to verify the presence and correctness of
specific NGAP protocol messages in network traffic captures.

:copyright:     Nokia Networks
:author:        Piotr Brzezicki, Mateusz Potoniec
:maintainer:    Piotr Brzezicki, Mateusz Potoniec
:contact:       piotr.brzezicki@nokia.com, mateusz.potoniec@nokia.com

Usage:
    from taf.rfrl.utilities.parsers.pcap_checker import Checker
    from taf.rfrl.utilities.parsers.pcap_checker.utils import PcapProvider
    from taf.rfrl.utilities.parsers.pcap_checker.messages import ngap_messages

    nr_cell_id = '123456'
    awaited_messages = [
        ngap_messages.create_initial_ue_message_registration_request(nr_cell_id),
        ngap_messages.INITIAL_CONTEXT_SETUP_REQUEST_PDU_SESSION,
        ngap_messages.INITIAL_CONTEXT_SETUP_RESPONSE_PDU_SESSION,
    ]

    forbidden_messages = [ngap_messages.UE_CONTEXT_RELEASE_COMMAND]

    pcap_provider = PcapProvider()
    checker = Checker(pcap_provider=pcap_provider)
    checker.expect_flow(
        pcap_file=pcap_file,
        display_filter='ngap',
        awaited_messages=awaited_messages,
        forbidden_messages=forbidden_messages
    )
"""


from taf.rfrl.utilities.parsers.pcap_checker.checker import AwaitedMessage
from taf.rfrl.utilities.parsers.pcap_checker.inspectors import HasInspector


INITIAL_CONTEXT_SETUP_REQUEST_PDU_SESSION = AwaitedMessage(
    name='InitialContextSetupRequest',
    find_by=[HasInspector('ngap.InitialContextSetupRequest_element')],
    verify_by=[HasInspector('ngap.PDUSessionResourceSetupListCxtReq')],
)


INITIAL_CONTEXT_SETUP_RESPONSE_PDU_SESSION = AwaitedMessage(
    name='InitialContextSetupResponse',
    find_by=[HasInspector('ngap.InitialContextSetupResponse_element')],
    verify_by=[HasInspector('ngap.PDUSessionResourceSetupListCxtRes')],
)


PDU_SESSION_RESOURCE_MODIFY_INDICATION = AwaitedMessage(
    name='PDUSessionResourceModifyIndication',
    find_by=[HasInspector('ngap.PDUSessionResourceModifyIndication_element')],
    verify_by=[],
)


PDU_SESSION_RESOURCE_MODIFY_CONFIRM = AwaitedMessage(
    name='PDUSessionResourceModifyConfirm',
    find_by=[HasInspector('ngap.PDUSessionResourceModifyConfirm_element')],
    verify_by=[],
)


UE_CONTEXT_RELEASE_COMMAND = AwaitedMessage(
    name='UEContextReleaseCommand',
    find_by=[HasInspector('ngap.UEContextReleaseCommand_element')],
    verify_by=[],
)


UE_CONTEXT_RELEASE_COMPLETE = AwaitedMessage(
    name='UEContextReleaseComplete',
    find_by=[HasInspector('ngap.UEContextReleaseComplete_element')],
    verify_by=[],
)


NG_RESET_ACKNOWLEDGE = AwaitedMessage(
    name='NGResetAcknowledge',
    find_by=[HasInspector('ngap.NGResetAcknowledge_element')],
    verify_by=[HasInspector('ngap.UE_associatedLogicalNG_connectionList')],
)


def create_initial_ue_message_registration_request(nr_cell_id: str, message_type: str = '0x41') -> AwaitedMessage:
    """
    Factory function to create an AwaitedMessage for InitialUEMessage with a specific NRCellIdentity.
    Create a parameterized AwaitedMessage for InitialUEMessage with a specific NRCellIdentity.

    :param nr_cell_id: The NRCellIdentity to verify in the message.
    :param message_type: The NAS message type to verify in the message.
    :return: An AwaitedMessage instance with the specified NRCellIdentity verification.
    """

    return AwaitedMessage(
        name='InitialUEMessage',
        find_by=[HasInspector('ngap.InitialUEMessage_element')],
        verify_by=[
            HasInspector('nas_5gs.mm.message_type', str(message_type)),
            HasInspector('ngap.NRCellIdentity', str(nr_cell_id)),
        ],
    )


def create_initial_ue_message(nr_cell_id: str) -> AwaitedMessage:
    """
    Factory function to create an AwaitedMessage for InitialUEMessage with a specific NRCellIdentity.
    Create a parameterized AwaitedMessage for InitialUEMessage with a specific NRCellIdentity.

    :param nr_cell_id: The NRCellIdentity to verify in the message.
    :return: An AwaitedMessage instance with the specified NRCellIdentity verification.
    """

    return AwaitedMessage(
        name='InitialUEMessage',
        find_by=[HasInspector('ngap.InitialUEMessage_element')],
        verify_by=[HasInspector('ngap.NRCellIdentity', str(nr_cell_id))],
    )
